package com.bank.approval.model;

import java.math.BigDecimal;
import java.util.Optional;

public class Applicant {
    private final String id;
    private final String name;
    private final String employer;       // nullable
    private final Integer creditScore;   // nullable
    private final BigDecimal income;     // nullable
    private final String guarantor;      // nullable — guarantor might have their own Optional fields

    public Applicant(String id, String name, String employer,
                     Integer creditScore, BigDecimal income, String guarantor) {
        this.id = id;
        this.name = name;
        this.employer = employer;
        this.creditScore = creditScore;
        this.income = income;
        this.guarantor = guarantor;
    }

    public String getId() { return id; }
    public String getName() { return name; }

    // ✅ Optional RETURN TYPES — nullable fields exposed as Optional at boundary
    public Optional<String> getEmployer() { return Optional.ofNullable(employer); }
    public Optional<Integer> getCreditScore() { return Optional.ofNullable(creditScore); }
    public Optional<BigDecimal> getIncome() { return Optional.ofNullable(income); }
    public Optional<String> getGuarantor() { return Optional.ofNullable(guarantor); }
}
