package com.bank.approval.service;

import com.bank.approval.dto.ApprovalResult;
import com.bank.approval.model.Applicant;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;
import java.util.*;

@Service
@Slf4j
public class LoanApprovalService {

    private final Map<String, Applicant> applicants = Map.of(
        "APP-001", new Applicant("APP-001", "Rajesh Kumar", "TCS", 780,
            new BigDecimal("1200000"), "Priya Sharma"),
        "APP-002", new Applicant("APP-002", "Amit Patel", null, 580,
            new BigDecimal("400000"), null),
        "APP-003", new Applicant("APP-003", "Deepa Reddy", "Wipro", null,
            null, "Vikram Singh")
    );

    // Simulated guarantor lookup (returns Optional)
    private Optional<Applicant> findGuarantor(String name) {
        return applicants.values().stream()
            .filter(a -> a.getName().equals(name))
            .findFirst();
    }

    public ApprovalResult processApplication(String applicantId) {
        List<String> steps = new ArrayList<>();

        // ═══ Step 1: Find applicant (orElseThrow — required) ═══
        Applicant applicant = Optional.ofNullable(applicants.get(applicantId))
            .orElseThrow(() -> {
                steps.add("❌ Applicant not found: " + applicantId);
                return new IllegalArgumentException("Applicant not found: " + applicantId);
            });
        steps.add("✅ Found: " + applicant.getName());

        // ═══ Step 2: Check employer (map — transform) ═══
        String employerStatus = applicant.getEmployer()
            .map(emp -> "Employed at " + emp)                // present → transform
            .orElse("Self-employed / Unemployed");            // absent → default
        steps.add("📋 Employer: " + employerStatus);

        // ═══ Step 3: Check credit score (filter — conditional) ═══
        boolean goodCredit = applicant.getCreditScore()
            .filter(score -> score >= 650)                    // keep only if >= 650
            .isPresent();                                      // true if present AND >= 650
        steps.add("📊 Credit: " + applicant.getCreditScore()
            .map(s -> s + " → " + (goodCredit ? "GOOD ✅" : "POOR ❌"))
            .orElse("NOT AVAILABLE ⚠"));

        // ═══ Step 4: Check income (map + filter chain) ═══
        boolean incomeOk = applicant.getIncome()
            .filter(inc -> inc.compareTo(new BigDecimal("500000")) >= 0)
            .map(inc -> true)
            .orElse(false);
        steps.add("💰 Income: " + applicant.getIncome()
            .map(i -> "Rs." + i + (incomeOk ? " ✅" : " ❌ (below 5L)"))
            .orElse("NOT PROVIDED ⚠"));

        // ═══ Step 5: Check guarantor (flatMap — nested Optional!) ═══
        // getGuarantor() returns Optional<String> (name)
        // findGuarantor(name) returns Optional<Applicant>
        // Without flatMap: map gives Optional<Optional<Applicant>> — useless!
        // With flatMap: we get Optional<Applicant> — clean!
        String guarantorStatus = applicant.getGuarantor()        // Optional<String>
            .flatMap(this::findGuarantor)                        // Optional<Applicant> (not nested!)
            .flatMap(Applicant::getCreditScore)                  // Optional<Integer>
            .filter(score -> score >= 700)                       // keep if good score
            .map(score -> "Guarantor verified (score: " + score + ") ✅")
            .orElse("No verified guarantor ⚠");
        steps.add("🤝 Guarantor: " + guarantorStatus);

        // ═══ Step 6: ifPresent — side effect (logging) ═══
        applicant.getIncome().ifPresent(inc ->
            log.info("Applicant {} income logged for audit: Rs.{}", applicantId, inc));

        // ═══ Decision ═══
        String decision = (goodCredit && incomeOk) ? "APPROVED ✅"
            : (!goodCredit && !incomeOk) ? "REJECTED ❌"
            : "MANUAL REVIEW 🔍";
        steps.add("📌 Decision: " + decision);

        return new ApprovalResult(applicantId, decision, steps);
    }
}
