package com.bank.approval.service;

import org.junit.jupiter.api.Test;
import java.util.Optional;
import static org.assertj.core.api.Assertions.*;

class IdiomaticOptionalTest {

    // ═══ map: transform if present ═══
    @Test
    void mapTransformsPresent() {
        String result = Optional.of("rajesh")
            .map(String::toUpperCase)
            .map(n -> "Welcome, " + n)
            .orElse("Welcome, Guest");
        assertThat(result).isEqualTo("Welcome, RAJESH");
    }

    @Test
    void mapReturnsEmptyForAbsent() {
        String result = Optional.<String>empty()
            .map(String::toUpperCase)
            .orElse("Welcome, Guest");
        assertThat(result).isEqualTo("Welcome, Guest");
    }

    // ═══ flatMap: avoid nested Optional ═══
    @Test
    void flatMapAvoidsNesting() {
        // Function that returns Optional:
        Optional<String> outer = Optional.of("RELIANCE");

        // map would give Optional<Optional<Integer>>:
        Optional<Optional<Integer>> nested = outer.map(s -> Optional.of(s.length()));
        // flatMap gives Optional<Integer>:
        Optional<Integer> flat = outer.flatMap(s -> Optional.of(s.length()));

        assertThat(flat).contains(8);
    }

    // ═══ filter: conditional keep ═══
    @Test
    void filterKeepsOnlyMatchingPresent() {
        Optional<Integer> good = Optional.of(780).filter(s -> s >= 650);
        Optional<Integer> poor = Optional.of(490).filter(s -> s >= 650);
        Optional<Integer> absent = Optional.<Integer>empty().filter(s -> s >= 650);

        assertThat(good).contains(780);
        assertThat(poor).isEmpty();    // present but didn't pass filter
        assertThat(absent).isEmpty();  // absent stays absent
    }

    // ═══ ifPresent/ifPresentOrElse: side effects ═══
    @Test
    void ifPresentExecutesOnlyWhenPresent() {
        StringBuilder log = new StringBuilder();

        Optional.of("Rajesh").ifPresent(n -> log.append("Found: ").append(n));
        Optional.empty().ifPresent(n -> log.append("SHOULD NOT APPEAR"));

        assertThat(log.toString()).isEqualTo("Found: Rajesh");
    }

    // ═══ Complete chain: the idiomatic way ═══
    @Test
    void completeIdiomaticChain() {
        record Account(String name, Optional<Integer> score) {}

        String result = Optional.of(new Account("Rajesh", Optional.of(780)))
            .flatMap(a -> a.score())        // flatMap: avoid Optional<Optional<Integer>>
            .filter(s -> s >= 700)          // filter: only good scores
            .map(s -> "Approved (score " + s + ")")  // map: transform
            .orElse("Manual Review");       // default

        assertThat(result).isEqualTo("Approved (score 780)");
    }

    // ═══ Anti-pattern vs idiomatic ═══
    @Test
    void antiPatternVsIdiomatic() {
        Optional<String> opt = Optional.of("RELIANCE");

        // ❌ Anti-pattern:
        String bad;
        if (opt.isPresent()) { bad = opt.get().toLowerCase(); }
        else { bad = "unknown"; }

        // ✅ Idiomatic:
        String good = opt.map(String::toLowerCase).orElse("unknown");

        assertThat(bad).isEqualTo(good);  // same result, different quality
    }
}
